try:live.write_text(new)
finally:live.chmod(original_mode)
diff=''.join(difflib.unified_diff(old.splitlines(keepends=True),new.splitlines(keepends=True),fromfile='scope-and-plan.original-bcf94c0cee6b9f98.md',tofile='scope-and-plan.md'))
(p/'c7d-documentation.diff').write_text(diff)
